#!/usr/bin/bash
#
# Efficiency experiments (RQ3, RQ4, RQ5):
#
#   1. 010-measure: one cmm_test measurement per file, skipped if it already exists
#   2. concatenate the measurements of these parameters into rq<N>_out.p<P>.tsv
#   3. plot the results into plots/p<P>/
#
# Instances are generated by ../data/run.sh and read from
# ../data/artificial_instances/. Run that first if they are not present.

set -euo pipefail

export LC_ALL=C

usage() {
    cat >&2 <<EOF
Usage: $0 [-P] -e <densities> -v <node counts> -x <taxid> -s <cutoff> -S <seed>
          -p <P> -r <trials> -k <K> -l <ells> -E <density> -V <node count> -L <ell> -d <D>

Options:
  -e <list>  edge densities of the instances, in percent (e.g. "05 10"); RQ4 sweeps them
  -v <list>  node counts of the instances (e.g. "100 200"); RQ3 sweeps them
  -x <int>   taxid of the organism the instances were sampled from
  -s <int>   STRING combined score cutoff the instances were sampled with
  -S <int>   seed the instances were sampled with
  -p <int>   max number of threads; RQ3/RQ4 use it, RQ5 sweeps 1..P
  -r <int>   number of trials per configuration
  -k <int>   number K of top motif pairs kept by cmm_test
  -l <list>  motif lengths for RQ3/RQ4 (e.g. "5 8"); each runs with d = 0..ell-1
  -E <int>   edge density for RQ3 and RQ5 (one of -e)
  -V <int>   node count for RQ4 and RQ5 (one of -v)
  -L <int>   motif length for RQ5 (one of -l)
  -d <int>   number of wildcards for RQ5, in [0,ell)
  -P         only concatenate and plot the existing measurements
  -h         show this help and exit
EOF
}

DENSITIES="" NODE_COUNTS="" INSTANCE_TAXID="" THRESHOLD="" SEED="" MAX_THREADS="" TRIALS="" K=""
ELLS="" FIXED_ED="" FIXED_V="" RQ5_ELL="" RQ5_D="" PLOT_ONLY=0

while getopts "e:v:x:s:S:p:r:k:l:E:V:L:d:Ph" opt
do
    case ${opt} in
        e) DENSITIES=${OPTARG} ;;
        v) NODE_COUNTS=${OPTARG} ;;
        x) INSTANCE_TAXID=${OPTARG} ;;
        s) THRESHOLD=${OPTARG} ;;
        S) SEED=${OPTARG} ;;
        p) MAX_THREADS=${OPTARG} ;;
        r) TRIALS=${OPTARG} ;;
        k) K=${OPTARG} ;;
        l) ELLS=${OPTARG} ;;
        E) FIXED_ED=${OPTARG} ;;
        V) FIXED_V=${OPTARG} ;;
        L) RQ5_ELL=${OPTARG} ;;
        d) RQ5_D=${OPTARG} ;;
        P) PLOT_ONLY=1 ;;
        h) usage; exit 0 ;;
        *) usage; exit 1 ;;
    esac
done

declare -A FLAG=(
    [DENSITIES]=-e [NODE_COUNTS]=-v [INSTANCE_TAXID]=-x [THRESHOLD]=-s [SEED]=-S [MAX_THREADS]=-p
    [TRIALS]=-r [K]=-k [ELLS]=-l [FIXED_ED]=-E [FIXED_V]=-V [RQ5_ELL]=-L [RQ5_D]=-d
)
# All options are needed with -P too, to select the measurements of these parameters.
REQUIRED="DENSITIES NODE_COUNTS INSTANCE_TAXID THRESHOLD SEED MAX_THREADS TRIALS K ELLS FIXED_ED FIXED_V RQ5_ELL RQ5_D"
INTEGERS="INSTANCE_TAXID THRESHOLD SEED MAX_THREADS TRIALS K FIXED_ED FIXED_V RQ5_ELL RQ5_D"
LISTS="DENSITIES NODE_COUNTS ELLS"
missing=""
for var in ${REQUIRED}
do
    [ -z "${!var}" ] && missing="${missing} ${FLAG[$var]}"
done
if [ -n "${missing}" ]
then
    echo "Error: missing required option(s):${missing}" >&2
    usage
    exit 1
fi
for var in ${INTEGERS}
do
    if ! [[ "${!var}" =~ ^[0-9]+$ ]]
    then
        echo "Error: ${FLAG[$var]} must be a non-negative integer, got '${!var}'." >&2
        exit 1
    fi
done
for var in ${LISTS}
do
    for value in ${!var}
    do
        if ! [[ "${value}" =~ ^[0-9]+$ ]]
        then
            echo "Error: ${FLAG[$var]} must be a list of non-negative integers, got '${!var}'." >&2
            exit 1
        fi
    done
done
for var in MAX_THREADS TRIALS K
do
    if [ "${!var}" -lt 1 ]
    then
        echo "Error: ${FLAG[$var]} must be >= 1, got '${!var}'." >&2
        exit 1
    fi
done
case " ${DENSITIES} " in
    *" ${FIXED_ED} "*) ;;
    *) echo "Error: -E ${FIXED_ED} is not one of the densities given with -e (${DENSITIES})." >&2; exit 1 ;;
esac
case " ${NODE_COUNTS} " in
    *" ${FIXED_V} "*) ;;
    *) echo "Error: -V ${FIXED_V} is not one of the node counts given with -v (${NODE_COUNTS})." >&2; exit 1 ;;
esac
case " ${ELLS} " in
    *" ${RQ5_ELL} "*) ;;
    *) echo "Error: -L ${RQ5_ELL} is not one of the motif lengths given with -l (${ELLS})." >&2; exit 1 ;;
esac
if [ "${RQ5_D}" -ge "${RQ5_ELL}" ]
then
    echo "Error: -d ${RQ5_D} must be smaller than -L ${RQ5_ELL}." >&2
    exit 1
fi

cd "$(dirname "$0")"

INSTANCE_DIR="../data/artificial_instances"
CMM_TEST="../bin/cmm_test"
VENV="venv"

# For a given ell, echo the wildcard counts d = 0 .. ell-1.
d_range() {
    seq 0 $(( $1 - 1 ))
}

# RQ5 thread counts: start at 1 and double up to MAX_THREADS.
rq5_thread_counts() {
    local threads=""
    local t=1
    while [ ${t} -lt ${MAX_THREADS} ]
    do
        threads="${threads} ${t}"
        t=$(( t * 2 ))
    done
    echo "${threads} ${MAX_THREADS}"
}

# Name of the instance with the given node count and edge density (as in ../data/run.sh).
instance() {
    echo "sampled_${INSTANCE_TAXID}_s${THRESHOLD}_S${SEED}_V$1_ed$2"
}

# Measurements of each research question, one per line: <instance> <ell> <d> <threads> <trial>.
rq3_measurements() {
    for trial in $(seq 1 ${TRIALS}); do
        for v in ${NODE_COUNTS}; do
            for ell in ${ELLS}; do
                for d in $(d_range ${ell}); do
                    echo "$(instance ${v} ${FIXED_ED}) ${ell} ${d} ${MAX_THREADS} ${trial}"
                done
            done
        done
    done
}
rq4_measurements() {
    for trial in $(seq 1 ${TRIALS}); do
        for ed in ${DENSITIES}; do
            for ell in ${ELLS}; do
                for d in $(d_range ${ell}); do
                    echo "$(instance ${FIXED_V} ${ed}) ${ell} ${d} ${MAX_THREADS} ${trial}"
                done
            done
        done
    done
}
rq5_measurements() {
    for trial in $(seq 1 ${TRIALS}); do
        for t in $(rq5_thread_counts); do
            echo "$(instance ${FIXED_V} ${FIXED_ED}) ${RQ5_ELL} ${RQ5_D} ${t} ${trial}"
        done
    done
}

# File of a measurement in 010-measure (as in 010-measure/Makefile).
perf_file() {
    local inst=$1 ell=$2 d=$3 threads=$4 trial=$5
    echo "${inst}/${inst}.l${ell}d${d}.k${K}.p${threads}.trial${trial}.perf"
}

# TSV of each research question, rebuilt at every run from the measurements of these parameters.
PLOT="./plot.py"
PLOT_DIR="plots/p${MAX_THREADS}"
OUT_RQ3="rq3_out.p${MAX_THREADS}.tsv"
OUT_RQ4="rq4_out.p${MAX_THREADS}.tsv"
OUT_RQ5="rq5_out.p${MAX_THREADS}.tsv"

# Setup virtual environment
if [ ! -d "${VENV}" ]
then
    echo "Creating virtual environment..." >&2
    python3 -m venv ${VENV}
    ${VENV}/bin/pip install -q -r requirements.txt
fi
source ${VENV}/bin/activate

if [ ${PLOT_ONLY} -eq 0 ]
then
    if [ ! -x "${CMM_TEST}" ]
    then
        echo "Error: ${CMM_TEST} not found or not executable. Run 'make -C ../src' first." >&2
        exit 1
    fi

    for rq in rq3 rq4 rq5
    do
        echo "=== Stage 010-measure: ${rq} ===" >&2
        ${rq}_measurements | while read -r inst ell d threads trial
        do
            ed=${inst##*_ed}
            fa="${INSTANCE_DIR}/ed${ed}/${inst}.fa"
            int="${INSTANCE_DIR}/ed${ed}/${inst}.int"
            if [ ! -f "${fa}" ] || [ ! -f "${int}" ]
            then
                echo "Error: missing instance ${fa} / ${int}. Run ../data/run.sh first." >&2
                exit 1
            fi
            vars=(INSTANCE=${inst} FASTA=$(realpath ${fa}) INTS=$(realpath ${int})
                  L=${ell} D=${d} K=${K} THREADS=${threads} TRIAL=${trial})
            if make -q -C 010-measure all "${vars[@]}"
            then
                echo "  skipping ${inst} ell=${ell} d=${d} threads=${threads} trial=${trial} -- already done" >&2
            else
                echo "  running ${inst} ell=${ell} d=${d} threads=${threads} trial=${trial}" >&2
                make -s -C 010-measure all "${vars[@]}"
            fi
        done
    done
fi

echo "Concatenating measurements..." >&2
for rq in rq3 rq4 rq5
do
    out_var="OUT_${rq^^}"
    out=${!out_var}
    inputs=()
    missing=0
    while read -r inst ell d threads trial
    do
        f="010-measure/$(perf_file ${inst} ${ell} ${d} ${threads} ${trial})"
        if [ -f "${f}" ]; then inputs+=("${f}"); else missing=$(( missing + 1 )); fi
    done < <(${rq}_measurements)
    if [ ${missing} -gt 0 ]
    then
        echo "  WARNING: ${missing} measurement(s) of ${rq} missing" >&2
    fi
    rm -f ${out}
    if [ ${#inputs[@]} -gt 0 ]
    then
        awk '{trial = FILENAME; sub(/.*\.trial/, "", trial); sub(/\.perf$/, "", trial);
              print trial "\t" $0}' "${inputs[@]}" > ${out}
    fi
done

## Plot
echo "Plotting results..." >&2
mkdir -p ${PLOT_DIR}

ANNOTATE="8:4 8:7 5:2 5:4"     # points annotated with max_rank
POLY_PAIRS="5:1 5:3 8:2 8:5"   # points given a polynomial fit on RQ3

# RQ3: log-scale both axes, quadratic fit on time, linear fit on memory per thread.
if [ ! -s "${OUT_RQ3}" ]
then
    echo "  ${OUT_RQ3} missing or empty, skipping rq3 plots" >&2
else
    echo "  rq3" >&2
    ${PLOT} \
        --input ${OUT_RQ3} \
        --rq rq3 \
        --output ${PLOT_DIR}/rq3 \
        --log-scale-time \
        --log-scale-mem \
        --fit-poly-time ${POLY_PAIRS} \
        --fit-poly-mem ${POLY_PAIRS} \
        --poly-degree-time 2 \
        --poly-degree-mem 1 \
        --no-poly-label \
        --max-rank ${ANNOTATE} \
        --mem-per-thread
fi

# RQ4: annotate selected points with max_rank (linear axes, no fits), memory per thread.
if [ ! -s "${OUT_RQ4}" ]
then
    echo "  ${OUT_RQ4} missing or empty, skipping rq4 plots" >&2
else
    echo "  rq4" >&2
    ${PLOT} \
        --input ${OUT_RQ4} \
        --rq rq4 \
        --output ${PLOT_DIR}/rq4 \
        --max-rank ${ANNOTATE} \
        --mem-per-thread
fi

# RQ5: speedup labels, log-scale both axes, total memory.
if [ ! -s "${OUT_RQ5}" ]
then
    echo "  ${OUT_RQ5} missing or empty, skipping rq5 plots" >&2
else
    echo "  rq5" >&2
    ${PLOT} \
        --input ${OUT_RQ5} \
        --rq rq5 \
        --output ${PLOT_DIR}/rq5 \
        --speedup \
        --rq5-ell ${RQ5_ELL} \
        --log-scale-time \
        --log-scale-mem
fi

echo "Done. Plots written to ${PLOT_DIR}/" >&2
